using System.Diagnostics;
using System.Globalization;
using System.Text.Json;
using System.Text.Json.Nodes;
using Idrak.Cli.Shared;
using Idrak.Models;
using Idrak.Models.Abstractions;

namespace Idrak.Cli.Commands.Run;

/// <summary>
/// <c>idrak run</c> with an encoder-decoder (a folder whose config.json names an architecture registered in
/// <see cref="PretrainedSeq2Seq"/> by a plug-in): the prompt is the source, encoded once; the answer is generated by the
/// library's <c>Seq2SeqGenerator</c> (sampled with the generation settings, or by beam search with <c>--beams</c>) and
/// streamed. Chat-only options (images, sounds, a system prompt, tools, a schema) and weight formats are refused naming
/// the option.
/// </summary>
internal static class Seq2SeqRun
{
    /// <summary>The beam option of run: <c>--beams N</c> (1, the default: no beam search).</summary>
    public const string BeamsOption = "--beams";

    /// <summary>The length-penalty option of run's beam search: <c>--length-penalty F</c> (default 1).</summary>
    public const string LengthPenaltyOption = "--length-penalty";

    /// <summary>The options' lines for run's usage text.</summary>
    public const string Help =
        "      --beams N          beam search with N beams (an encoder-decoder; default 1: the sampler)\n" +
        "      --length-penalty F the beams' length penalty (default 1: the mean log-probability; 0: the sum)\n";

    /// <summary>
    /// The architecture of <paramref name="folder"/> when its config.json names one an encoder-decoder family registered
    /// (<see cref="PretrainedSeq2Seq"/>), else null (a decoder, a GGUF file, a folder without config.json).
    /// </summary>
    public static string? Architecture(string folder)
    {
        string file = Path.Combine(folder, "config.json");
        if (!Directory.Exists(folder) || !File.Exists(file))
        {
            return null;
        }

        try
        {
            return JsonNode.Parse(File.ReadAllText(file)) is JsonObject config && config["architectures"] is JsonArray { Count: > 0 } names
                   && names[0] is JsonValue value && value.GetValueKind() == JsonValueKind.String && PretrainedSeq2Seq.Find(value.GetValue<string>()) is not null
                ? value.GetValue<string>() : null;
        }
        catch (JsonException)
        {
            return null;                                                    // read (and reported) by the decoder's loader
        }
    }

    /// <summary>The beam settings of the command line: the beams (1 when not given) and the length penalty.</summary>
    public static (int Beams, float LengthPenalty) Beams(CommandContext context)
    {
        int beams = 1;
        if (context.Option(BeamsOption) is { } text && !(int.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out beams) && beams >= 1))
        {
            throw new UsageException($"{BeamsOption} needs a whole number of 1 or more (1: no beam search), not '{text}'.");
        }

        float penalty = 1f;
        if (context.Option(LengthPenaltyOption) is { } value
            && !(float.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out penalty) && float.IsFinite(penalty)))
        {
            throw new UsageException($"{LengthPenaltyOption} needs a number (1: the mean log-probability), not '{value}'.");
        }

        return (beams, penalty);
    }

    /// <summary>Answers <paramref name="prompt"/> with the encoder-decoder in <paramref name="folder"/>; the exit code.</summary>
    public static int Run(CommandContext context, ModelChoices.ModelChoice choice, string folder, string architecture, string prompt, GenerationSettings settings,
        string? outFile)
    {
        string model = choice.Model;
        string Refused(string option, string why) => $"{option}: {model} is an encoder-decoder ({architecture}); {why}.";
        foreach (string option in new[] { "--image", "--audio" })
        {
            if (context.Options(option).Count > 0)
            {
                throw new UsageException(Refused(option, "it reads text only"));
            }
        }

        foreach (var (option, given) in new[]
                 {
                     ("--schema", context.Option("--schema") is not null), ("--mcp", context.Options("--mcp").Count > 0), ("--tools", settings.ToolAssemblies.Count > 0),
                     ("--system", settings.System is not null), ("--think", settings.Think is not null),
                 })
        {
            if (given)
            {
                throw new UsageException(Refused(option, "it answers its source text, with no chat template, tools or reasoning"));
            }
        }

        if (choice.Weights is { } weights && weights.ToLowerInvariant() is not ("float32" or "f32"))
        {
            throw new UsageException(Refused("--weights", $"its weights are read as stored (float32), not as {weights}"));
        }

        if (choice.HeadWeights is not null || choice.Adapter is not null)
        {
            throw new UsageException(Refused(choice.Adapter is not null ? "--adapter" : "--head-weights", "it is read as stored, without an adapter or a head format"));
        }

        var (beams, penalty) = Beams(context);
        var layout = ModelChoices.CacheLayout(choice);
        var device = context.Device;
        var watch = Stopwatch.StartNew();
        PretrainedSeq2SeqModel loaded;
        using (var progress = new ProgressLine(context, $"loading {model} on {device}", unit: ProgressUnit.Elapsed))
        {
            loaded = PretrainedSeq2SeqModel.Load(folder, new PretrainedEncoderOptions { Device = device });
            progress.Clear();
        }

        using var owner = loaded;
        context.Detail($"loaded {model} ({architecture}, an encoder-decoder) in {watch.Elapsed.TotalSeconds:F1} s on {device}");
        var generator = loaded.CreateGenerator(cacheLayout: layout);
        var options = settings.ToOptions(loaded.Model.MaxTargetPositions) with { NumBeams = beams, LengthPenalty = penalty };
        using var interrupt = new Interrupt(context);           // the first Ctrl+C (or --timeout) stops after the current token
        var text = new System.Text.StringBuilder();
        string reason = "length";
        Idrak.Abstraction.Generation.GenerationStats? stats = null;
        try
        {
            foreach (var chunk in generator.Stream(prompt, options, interrupt.Token))
            {
                text.Append(chunk.Text);
                if (!context.Json && chunk.Text.Length > 0)
                {
                    context.Output.Write(chunk.Text);
                    context.Output.Flush();
                }

                if (chunk.Done)
                {
                    reason = chunk.DoneReason ?? reason;
                    stats = chunk.Stats;
                }
            }
        }
        catch (OperationCanceledException)
        {
            context.Error(interrupt.TimedOut ? $"stopped: --timeout {Units.Duration(context.Timeout!.Value)} ran out" : "stopped");
            return ExitCodes.Failed;
        }

        if (!context.Json)
        {
            context.Output.WriteLine();
        }

        stats ??= new Idrak.Abstraction.Generation.GenerationStats(0, TimeSpan.Zero, 0, TimeSpan.Zero, TimeSpan.Zero, 0);
        if (context.Verbose && !context.Json)
        {
            context.ErrorOutput.WriteLine($"[{stats.GeneratedTokens} tokens, {stats.TokensPerSecond:F1} tokens/s, source {stats.PromptTokens} tokens encoded in "
                                          + $"{stats.PromptDuration.TotalSeconds:F2} s{(beams > 1 ? $", {beams} beams" : "")}{(reason == "length" ? ", stopped at the token limit" : "")}]");
        }

        var json = new JsonObject
        {
            ["model"] = model,
            ["device"] = device.ToString(),
            ["architecture"] = architecture,
            ["text"] = text.ToString(),
            ["done_reason"] = reason,
            ["prompt_tokens"] = stats.PromptTokens,
            ["generated_tokens"] = stats.GeneratedTokens,
            ["prompt_seconds"] = Math.Round(stats.PromptDuration.TotalSeconds, 4),
            ["generation_seconds"] = Math.Round(stats.GenerationDuration.TotalSeconds, 4),
            ["tokens_per_second"] = Math.Round(stats.TokensPerSecond, 2),
            ["beams"] = beams,
        };
        context.WriteJson(json);
        RunCommand.WriteOut(context, outFile, text.ToString(), json);
        return ExitCodes.Ok;
    }
}
